import java.nio.file.*;import java.nio.file.attribute.*;import java.io.*;
public class FolderReport {public static void main(String[] args)throws Exception{Path root=Paths.get(args.length>0?args[0]:".");Path report=Paths.get("folder-report.txt");try(BufferedWriter w=Files.newBufferedWriter(report)){try(var paths=Files.walk(root)){paths.filter(Files::isRegularFile).forEach(p->{try{BasicFileAttributes a=Files.readAttributes(p,BasicFileAttributes.class);w.write(p.getFileName()+" | "+a.size()+" bytes | "+a.lastModifiedTime());w.newLine();}catch(IOException e){throw new UncheckedIOException(e);}});}}System.out.println("Report written to "+report.toAbsolutePath());}}
